{"command": "cd /tmp && cat > /tmp/bfglobal.py <<'EOF'
import string,os,subprocess,shutil,re,sys,json
d='/tmp/extd'
chars=string.ascii_lowercase+string.digits
def gen(n):
    if n==1: return list(chars)
    return [a+b for a in chars for b in chars]
mapping={}
def run(cands):
    if os.path.exists(d): shutil.rmtree(d)
    os.makedirs(d)
    for e in cands:
        open(os.path.join(d,'f_'+e+'.'+e),'w').write('x\n')
    out=subprocess.run(['/workspace/executable',d,'-f'],capture_output=True,text=True).stdout
    cur=None
    for line in out.split('\n'):
        s=line
        if not s.startswith(' '): continue
        toks=s.split()
        if len(toks)>=5 and all(t.isdigit() for t in toks[-5:]) and len(toks)==6:
            cur=' '.join(toks[:-5]); continue
        if len(toks)>=5 and all(t.isdigit() for t in toks[-4:]) and len(toks)==5:
            path=toks[0]
            ext=path.rsplit('.',1)[1]
            mapping[ext]=cur
            continue
n=len(sys.argv)
if sys.argv[1]=='3':
    cands=list(chars)+gen(2)+[a+b+c for a in chars for b in chars for c in chars]
else:
    pre=sys.argv[2]
    cands=[pre+x for x in gen(int(sys.argv[3]))]
print(len(cands))
chunk=3000
for i in range(0,len(cands),chunk):
    run(cands[i:i+chunk])
print(len(mapping))
json.dump(mapping, open('/tmp/extmap_'+sys.argv[1]+('.json' if n==2 else '_'+sys.argv[2]+'_'+sys.argv[3]+'.json'),'w'))
