# files for languages with no extensions
FILES={'Meson':['meson.build'],'NuGet Config':['nuget.config'],'Pacman\'s makepkg':['pkgbuild'],'Scons':['sconstruct']}
def tokprobe(tokens):
    out={}
    for tok in tokens:
        d='/tmp/tokd'
        if os.path.exists(d): shutil.rmtree(d)
        os.makedirs(d)
        names=[]
        for n,exts in LANG:
            if exts: fn='f%03d.%s'%(len(names), exts[0])
            else: fn=FILES[n][0]
            open(os.path.join(d,fn),'w').write(tok+' comment\nX\n')
            names.append((n,fn))
        r=subprocess.run(['/workspace/executable',d,'-f'],capture_output=True,text=True).stdout
        cur=None
        res={}
