            m2=re.match(r'^ (\S+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s*$', line)
            if m2 and cur:
                base=os.path.basename(m2.group(1))
                res[base]=int(m2.group(4))  # comments
        for n,fn in names:
            out.setdefault(n,{})[tok]=res.get(fn,-1)
    return out
