minim={}
for line in open('/tmp/minimal.txt'):
    idx=line.rstrip('\n').find(' [')
    n=line[:idx]
    minim[n]=ast.literal_eval(line[idx+1:])
opens=[(n,t) for n,ts in minim.items() for t,c in ts if c==2 and t not in (' ',)]
closers=['*/','+/', '*)', '-}', '-->', '--->', '--%>', '|#', '=end', '=cut', '!}', '}}', '#}', '*}', '#>', '-/', '*@', '"""', ']', ')', '}#', '*#', ')#', '}', '--', ']#']
res={}
for tok,c in opens:
    d='/tmp/closed'
    if os.path.exists(d): shutil.rmtree(d)
    os.makedirs(d)
    names_ok=[]
    for n in names:
        ts=[t for t,cc in minim.get(n,[]) if cc==2]
        if tok not in ts: continue
        e=ext_for(n)
        fn=e[0] if e else FILES[n][0]
        open(os.path.join(d,fn),'w').write(tok+' a\n'+closers+'\nX\n')
        names_ok.append((n,fn))
    r=subprocess.run(['/workspace/executable',d,'-f'],capture_output=True,text=True).stdout
    cur=None; resx={}
