        if m: cur=m.group(1).strip(); continue
        m2=re.match(r'^ (\S+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s*$', line)
        if m2 and cur: resx[os.path.basename(m2.group(1))]=int(m2.group(4))
    for n,fn in names_ok: res.setdefault(tok,{})[n]=resx.get(fn,-1)
for tok in res:
    good=[n for n,c in res[tok].items() if c==2]
    print(tok, 'CLOSED' if len(good)==len(res[tok]) else ('PARTIAL %d/%d'%(len(good),len(res[tok]))), '' if len(good)==len(res[tok]) else ('FAIL:'+str([n for n,c in res[tok].items() if c!=2])))
