names=[l.rstrip('\n').split('|')[1] for l in open('/tmp/langlist.txt')][1:]
FILES={'Meson':['meson.build'],'NuGet Config':['nuget.config'],"Pacman's makepkg":['pkgbuild'],'Scons':['sconstruct']}
# map name -> ext[0] or file
def ext_for(n):
    for l in open('/tmp/langlist.txt'):
        i,nn,e=l.rstrip('\n').split('|')
        if nn==n: return [] if e=='<None>' else [e.split(', ')[0]]
# minimal tokens parsed from minimal.txt
minim={}
for line in open('/tmp/minimal.txt'):
    n=line.rstrip('\n').split(' [')[0]
    rest=line.rstrip('\n')[len(n)+2:]
    minim[n]=ast.literal_eval(rest) if False else eval(rest)
import ast
minim={}
for line in open('/tmp/minimal.txt'):
    idx=line.rstrip('\n').find(' [')
    n=line[:idx]
    minim[n]=ast.literal_eval(line[idx+1:])
opens=[(n,t) for n,ts in minim.items() for t,c in ts if c==2 and t not in (' ',)]
closers=['*/','+/', '*)', '-}', '-->', '--->', '--%>', '|#', '=end', '=cut', '!}', '}}', '#}', '*}', '#>', '-/', '*@', '"""', ']', ')', '}#', '*#', ')#', '}', '--', ']#']
res={}
for tok,c in opens:
    d='/tmp/closed'
    if os.path.exists(d): shutil.rmtree(d)
    os.makedirs(d)
    names_ok=[]
    for n in names:
        ts=[t for t,cc in minim.get(n,[]) if cc==2]
        if tok not in ts: continue
        e=ext_for(n)
        fn=e[0] if e else FILES[n][0]
        open(os.path.join(d,fn),'w').write(tok+' a\n'+closers+'\nX\n')
        names_ok.append((n,fn))
    r=subprocess.run(['/workspace/executable',d,'-f'],capture_output=True,text=True).stdout
    cur=None; resx={}
    for line in r.split('\n'):
        if not line.startswith(' '): continue
        m=re.match(r'^ (.+?)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s*$', line)
        if m: cur=m.group(1).strip(); continue
        m2=re.match(r'^ (\S+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s*$', line)
        if m2 and cur: resx[os.path.basename(m2.group(1))]=int(m2.group(4))
    for n,fn in names_ok: res.setdefault(tok,{})[n]=resx.get(fn,-1)
for tok in res:
    good=[n for n,c in res[tok].items() if c==2]
    print(tok, 'CLOSED' if len(good)==len(res[tok]) else ('PARTIAL %d/%d'%(len(good),len(res[tok]))), '' if len(good)==len(res[tok]) else ('FAIL:'+str([n for n,c in res[tok].items() if c!=2])))
EOF
python3 /tmp/closeprobe.py 2>&1 | head -40

