use std::collections::BTreeMap;
use crate::langs::{LangDef, Kind, LANGS};

#[derive(Default, Clone, Debug, PartialEq)]
pub struct Stats {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
}

impl Stats {
    pub fn lines(&self) -> usize {
        self.blanks + self.code + self.comments
    }
    pub fn add(&mut self, o: &Stats) {
        self.blanks += o.blanks;
        self.code += o.code;
        self.comments += o.comments;
    }
    pub fn is_empty(&self) -> bool {
        self.blanks == 0 && self.code == 0 && self.comments == 0
    }
}

#[derive(Default, Clone, Debug, PartialEq)]
pub struct BlobStats {
    pub stats: Stats,
    pub blobs: BTreeMap<String, BlobStats>,
}

impl BlobStats {
    pub fn total(&self) -> Stats {
        let mut s = self.stats.clone();
        for b in self.blobs.values() {
            s.add(&b.total());
        }
        s
    }
}

pub type Blobs = BTreeMap<String, BlobStats>;

fn is_blank(line: &str) -> bool {
    line.trim().is_empty()
}

/// Split text into lines, keeping information about trailing newline
struct LineIter<'a> {
    s: &'a str,
    pos: usize,
}
impl<'a> LineIter<'a> {
    fn new(s: &'a str) -> Self {
        LineIter { s, pos: 0 }
    }
}
impl<'a> Iterator for LineIter<'a> {
    type Item = (usize, usize); // start,end offsets (end is index of newline or len)
    fn next(&mut self) -> Option<(usize, usize)> {
        if self.pos > self.s.len() {
            return None;
        }
        if self.pos == self.s.len() {
            self.pos += 1;
            return None;
        }
        let rest = &self.s[self.pos..];
        match rest.find('\n') {
            Some(i) => {
                let (a, b) = (self.pos, self.pos + i);
                self.pos = b + 1;
                Some((a, b))
            }
            None => {
                let (a, b) = (self.pos, self.s.len());
                self.pos = self.s.len() + 1;
                Some((a, b))
            }
        }
    }
}

fn lines_vec(text: &str) -> Vec<(usize, usize)> {
    LineIter::new(text).collect()
}

/// Count lines of a normal language, returning stats plus embedded language blobs
fn count_normal(lang: &LangDef, text: &str) -> (Stats, Blobs) {
    let mut st = Stats::default();
    let mut blobs: Blobs = BTreeMap::new();
    let lcs = lang.line_comments;
    let mls = lang.multi_line;
    let quotes = lang.quotes;
    let mut in_ml: Option<(usize, usize, usize)> = None; // open index, close index, depth
    let mut in_str: Option<(usize, bool)> = None; // quote index, escape flag

    for (start, end) in lines_vec(text) {
        let line = &text[start..end];
        let was_ml = in_ml.is_some();
        let was_str = in_str.is_some();
        let mut code_seen = false;
        let mut comment_seen = false;
        let bytes = line.as_bytes();
        let mut i = 0usize;
        while i < bytes.len() {
            if let Some((qi, esc)) = in_str {
                let c = bytes[i] as char;
                if esc {
                    in_str = Some((qi, false));
                    i += 1;
                    code_seen = true;
                    continue;
                }
                if c == '\\' && lang.line_comments.iter().all(|t| t.as_bytes() != b"\\") {
                    // escape handling: skip next char if we are inside a string for most langs
                    in_str = Some((qi, true));
                    i += 1;
                    code_seen = true;
                    continue;
                }
                if c == quotes[qi] {
                    in_str = None;
                    i += 1;
                    continue;
                }
                code_seen = true;
                i += 1;
                continue;
            }
            if let Some((oi, ci, depth)) = in_ml {
                let close = mls[ci].1;
                let open = mls[oi].0;
                if line[i..].starts_with(close) {
                    let d = depth - 1;
                    if d == 0 {
                        in_ml = None;
                    } else {
                        in_ml = Some((oi, ci, d));
                    }
                    comment_seen = true;
                    i += close.len();
                    continue;
                }
                if lang.nested && line[i..].starts_with(open) {
                    in_ml = Some((oi, ci, depth + 1));
                    comment_seen = true;
                    i += open.len();
                    continue;
                }
                comment_seen = true;
                i += 1;
                continue;
            }
            let c = bytes[i] as char;
            if c.is_whitespace() {
                i += 1;
                continue;
            }
            // try tokens: longest first
            let mut matched = false;
            // multi-line tokens
            for (k, (o, _c)) in mls.iter().enumerate() {
                if line[i..].starts_with(o.as_bytes()) {
                    // prefer line comment if it also matches and is at line start and no code seen
                    let line_match = lcs.iter().position(|t| t.as_bytes() == o.as_bytes());
                    if line_match.is_some() && !code_seen {
                        comment_seen = true;
                        break;
                    }
                    in_ml = Some((k, k, 1));
                    comment_seen = true;
                    i += o.len();
                    matched = true;
                    break;
                }
            }
            if matched {
                continue;
            }
            for t in lcs.iter() {
                if line[i..].starts_with(t.as_bytes()) {
                    comment_seen = true;
                    matched = true;
                    break;
                }
            }
            if matched {
                break;
            }
            for (k, q) in quotes.iter().enumerate() {
                if c == *q {
                    in_str = Some((k, false));
                    code_seen = true;
                    matched = true;
                    break;
                }
            }
            if matched {
                i += 1;
                continue;
            }
            code_seen = true;
            i += 1;
        }
        // classify
        if in_str.is_some() && was_str {
            st.code += 1;
            continue;
        }
        if was_ml {
            st.comments += 1;
            continue;
        }
        if code_seen {
            st.code += 1;
        } else if comment_seen {
            st.comments += 1;
        } else {
            st.blanks += 1;
        }
    }
    (st, blobs)
}
RSEOF
echo done"}

