            // find the longest token match
            let mut best: Option<(usize, usize)> = None; // (len, kind) kind: 0=ml,1=line,2=quote
            for (k, (o, _)) in self.lang.multi_line.iter().enumerate() {
                if line[i..].starts_with(o) {
                    let l = o.len();
                    if best.map(|(bl, _)| l > bl).unwrap_or(true) {
                        best = Some((l, 0));
                        // remember index
                        best = Some((l, 100 + k));
                    }
                }
            }
            for (k, t) in self.lang.line_comments.iter().enumerate() {
                if line[i..].starts_with(t.as_bytes()) {
                    let l = t.len();
                    if best.map(|(bl, bk)| l > bl || (l == bl && bk >= 100)).unwrap_or(true) {
                        best = Some((l, 200 + k));
                    }
                }
            }
            for (k, q) in self.lang.quotes.iter().enumerate() {
                if c == q.chars().next().unwrap() {
                    if best.is_none() {
                        best = Some((1, 300 + k));
                    }
                }
            }
            match best {
                Some((l, kind)) if kind >= 200 => {
                    comment_seen = true;
                    break;
                }
                Some((l, kind)) if kind >= 100 => {
                    let k = kind - 100;
                    self.in_ml = Some((k, 1));
                    comment_seen = true;
                    i += l;
                }
                Some((_, kind)) => {
                    let k = kind - 300;
                    self.in_str = Some(k);
                    code_seen = true;
                    i += 1;
                }
                None => {
                    code_seen = true;
                    i += 1;
                }
            }
        }
        (code_seen, comment_seen)
    }
}

pub fn count(lang: &LangDef, text: &str) -> (Stats, Blobs) {
    match lang.kind {
        Kind::Comments => count_comments_only(text),
        Kind::Markdown => count_markdown(lang, text, true),
        Kind::Html => count_html(lang, text),
        Kind::Rust => count_rust(lang, text),
        Kind::Normal => {
            let mut p = Parser::new(lang);
            let mut st = Stats::default();
            for (start, end) in Lines::new(text) {
                let line = &text[start..end];
                let was_ml = p.in_ml.is_some();
                let was_str = p.in_str.is_some();
                let (code_seen, comment_seen) = p.scan(line);
                classify(&mut st, was_ml, was_str, code_seen, comment_seen);
            }
            (st, BTreeMap::new())
        }
    }
}

fn classify(st: &mut Stats, was_ml: bool, was_str: bool, code_seen: bool, comment_seen: bool) {
    if was_ml {
        st.comments += 1;
    } else if was_str || code_seen {
        st.code += 1;
    } else if comment_seen {
        st.comments += 1;
    } else {
        st.blanks += 1;
    }
}

fn count_comments_only(text: &str) -> (Stats, Blobs) {
    let mut st = Stats::default();
    for (start, end) in Lines::new(text) {
        let line = &text[start..end];
        if line.trim().is_empty() {
            st.blanks += 1;
        } else {
            st.comments += 1;
        }
    }
    (st, BTreeMap::new())
}

/// Look up a language by its name, case-insensitively (for markdown info strings)
pub fn lang_by_name_lower(name: &str) -> Option<usize> {
    LANGS
        .iter()
        .position(|l| l.name.to_lowercase() == name.to_lowercase())
}

/// Look up a language whose lowercased name exactly equals `name` (case sensitive)
pub fn lang_by_lower_exact(name: &str) -> Option<usize> {
    LANGS.iter().position(|l| {
        let mut lower = String::new();
        lower.push_str(&l.name.to_lowercase());
        lower == name
    })
}

fn fence_info_language(info: &str) -> Option<(usize, usize)> {
    // returns (lang index, length of matched name within info)
    if info.is_empty() {
        return None;
    }
    if info.starts_with(|c: char| c.is_whitespace()) {
        return None;
    }
    // first token split on whitespace and commas
    let mut end = info.len();
    for (i, c) in info.char_indices() {
        if c == ' ' || c == '\t' || c == ',' {
            end = i;
            break;
        }
    }
    let tok = &info[..end];
    if tok.is_empty() {
        return None;
    }
    lang_by_name_lower(tok).map(|ix| (ix, tok.len()))
}

fn count_markdown(lang: &LangDef, text: &str, comments_only: bool) -> (Stats, Blobs) {
    let mut st = Stats::default();
    let mut blobs: Blobs = BTreeMap::new();
    let s = text.as_bytes();
    let mut cursor = 0usize;
    // offset of the last processed line end
    while cursor < text.len() {
        let nl = text[cursor..].find('\n').map(|i| cursor + i);
        let end = nl.unwrap_or(text.len());
        let line = &text[cursor..end];
        let trimmed = line.trim_start();
        let lead = line.len() - trimmed.len();
        if trimmed.starts_with("```") {
            let info = &trimmed[3..];
            if let Some((li, name_len)) = fence_info_language(info) {
                let child = &LANGS[li];
                st.comments += 1;
                // determine the block start
                let has_ws = {
                    let t = info.trim_end();
                    t.contains(|c: char| c == ' ' || c == '\t')
                };
                let block_start = if has_ws {
                    cursor + lead + 3 + name_len
                } else if end < text.len() {
                    end + 1
                } else {
                    text.len()
                };
                // find the closing fence line
                let mut closing: Option<usize> = None;
                let mut p = if end < text.len() { end + 1 } else { text.len() };
                while p < text.len() {
                    let nl2 = text[p..].find('\n').map(|i| p + i);
                    let e2 = nl2.unwrap_or(text.len());
                    let l2 = &text[p..e2];
                    if l2.trim_start().starts_with("```") {
                        closing = Some(p);
                        break;
                    }
                    p = if e2 < text.len() { e2 + 1 } else { text.len() + 1 };
                }
                let (block, after) = match closing {
                    Some(cs) => (&text[block_start..cs], cs + 3),
                    None => (&text[block_start..], text.len()),
                };
                let (cst, cblobs) = count(child, block);
                let entry = blobs.entry(child.name.to_string()).or_default();
                entry.stats.add(&cst);
                for (k, v) in cblobs {
                    let e2 = entry.blobs.entry(k).or_default();
                    e2.stats.add(&v.stats);
                    for (k2, v2) in v.blobs {
                        let e3 = e2.blobs.entry(k2).or_default();
                        e3.stats.add(&v2.stats);
                        for (k3, v3) in v3.blobs {
                            e3.blobs.insert(k3, v3);
                        }
                    }
                }
                // continue after the closing fence's backticks
                cursor = after;
                // if there is a remainder on this line, count it as a line
                if cursor < text.len() {
                    let nl3 = text[cursor..].find('\n').map(|i| cursor + i);
                    let e3 = nl3.unwrap_or(text.len());
                    let rem = &text[cursor..e3];
                    if !rem.is_empty() {
                        if comments_only {
                            if rem.trim().is_empty() {
                                st.blanks += 1;
                            } else {
                                st.comments += 1;
                            }
                        } else {
                            let (a, b) = count_line_normal(lang, rem);
                            st.add(&a);
                            merge(&mut blobs, b);
                        }
                    }
                    cursor = if e3 < text.len() { e3 + 1 } else { text.len() };
                }
                continue;
            }
        }
        if comments_only {
            if line.trim().is_empty() {
                st.blanks += 1;
            } else {
                st.comments += 1;
            }
        } else {
            let (a, b) = count_line_normal(lang, line);
            st.add(&a);
            merge(&mut blobs, b);
        }
        cursor = if end < text.len() { end + 1 } else { text.len() };
    }
    (st, blobs)
}

fn merge(blobs: &mut Blobs, other: Blobs) {
    for (k, v) in other {
        let e = blobs.entry(k).or_default();
        e.stats.add(&v.stats);
        for (k2, v2) in v.blobs {
            let e2 = e.blobs.entry(k2).or_default();
            e2.stats.add(&v2.stats);
            for (k3, v3) in v2.blobs {
                e2.blobs.insert(k3, v3);
            }
        }
    }
}

fn count_line_normal(lang: &LangDef, line: &str) -> (Stats, Blobs) {
    let mut p = Parser::new(lang);
    let was_ml = p.in_ml.is_some();
    let was_str = p.in_str.is_some();
    let (code_seen, comment_seen) = p.scan(line);
    let mut st = Stats::default();
    classify(&mut st, was_ml, was_str, code_seen, comment_seen);
    (st, BTreeMap::new())
}

fn count_rust(lang: &LangDef, text: &str) -> (Stats, Blobs) {
    let mut st = Stats::default();
    let mut blobs: Blobs = BTreeMap::new();
    let mut doc_parts: Vec<String> = Vec::new();
    let mut have_doc = false;
    let lines: Vec<(usize, usize)> = Lines::new(text).collect();
    let mut i = 0usize;
    while i < lines.len() {
        let (start, end) = lines[i];
        let line = &text[start..end];
        let trimmed = line.trim_start();
        let is_doc = !trimmed.is_empty()
            && (trimmed.starts_with("///") || trimmed.starts_with("//!"));
        if is_doc {
            have_doc = true;
            let prefix_len = if trimmed.starts_with("///") { 3 } else { 3 };
            doc_parts.push(trimmed[prefix_len..].to_string());
            i += 1;
            // consume blank lines that are followed by another doc line
            while i < lines.len() {
                let (s2, e2) = lines[i];
                let l2 = &text[s2..e2];
                if l2.trim().is_empty() {
                    if i + 1 < lines.len() {
                        let (s3, e3) = lines[i + 1];
                        let l3 = &text[s3..e3];
                        let t3 = l3.trim_start();
                        if t3.starts_with("///") || t3.starts_with("//!") {
                            i += 1;
                            continue;
                        }
                    }
                    break;
                }
                break;
            }
            continue;
        }
        // count this line normally
        let mut p = Parser::new(lang);
        let was_ml = p.in_ml.is_some();
        let was_str = p.in_str.is_some();
        let (code_seen, comment_seen) = p.scan(line);
        classify(&mut st, was_ml, was_str, code_seen, comment_seen);
        i += 1;
    }
    if have_doc {
        let blob = doc_parts.join("\n");
        let blob = blob.trim();
        if !blob.is_empty() {
            let md = LANGS.iter().find(|l| l.name == "Markdown").unwrap();
            let (mst, mblobs) = count(md, blob);
            let mut e = BlobStats::default();
            e.stats = mst;
            e.blobs = mblobs;
            blobs.insert("Markdown".to_string(), e);
        }
    }
    (st, blobs)
}

fn html_tag_children(lang: &LangDef) -> &'static [(&'static str, &'static str, bool, &'static str)] {
    match lang.name {
        "HTML" => &[("script", "JavaScript", true, ""), ("style", "CSS", true, "")],
        "Vue" => &[
            ("script", "JavaScript", false, ""),
            ("style", "CSS", true, ""),
            ("template", "HTML", true, ""),
        ],
        "Svelte" => &[
            ("script", "JavaScript", false, ""),
            ("style", "CSS", true, ""),
            ("template", "", true, ""),
        ],
        _ => &[],
    }
}

fn count_html(lang: &LangDef, text: &str) -> (Stats, Blobs) {
    let mut st = Stats::default();
    let mut blobs: Blobs = BTreeMap::new();
    let tags = html_tag_children(lang);
    // We walk the text, splitting into segments: normal text and tag blocks.
    let lower = text.to_lowercase();
    let mut positions: Vec<(usize, usize, usize)> = Vec::new(); // start,end,tag index
    for (ti, (tag, _child, _uselang, _default)) in tags.iter().enumerate() {
        let open = format!("<{}", tag);
        let close = format!("</{}>", tag);
        let mut from = 0usize;
        while let Some(rel) = lower[from..].find(&open) {
            let start = from + rel;
            // must be followed by whitespace, '>' or attributes
            let after = &text[start + open.len()..];
            if !(after.starts_with('>')
                || after.starts_with(|c: char| c.is_whitespace()))
            {
                from = start + open.len();
                continue;
            }
            // find the end of the opening tag
            let gt = match after.find('>') {
                Some(g) => start + open.len() + g,
                None => break,
            };
            // find the closing tag
            let close_rel = match lower[gt..].find(&close) {
                Some(c) => c,
                None => break,
            };
            let block_start = gt + 1;
            let block_end = gt + close_rel;
            positions.push((block_start, block_end, ti));
            from = gt + close_rel + close.len();
        }
    }
    positions.sort();
    let mut cursor = 0usize;
    for (bs, be, ti) in positions {
        // count the text before the block
        let seg = &text[cursor..bs];
        count_segment(lang, seg, &mut st, &mut blobs);
        // the child language
        let tag = tags[ti];
        let (child_name, use_lang, default) = (tag.1, tag.2, tag.3);
        let open_tag_end = bs;
        // find the lang attribute in the opening tag
        let tag_text = &text[bs.saturating_sub(200)..bs];
        let mut chosen = default;
        if use_lang {
            if let Some(li) = find_lang_attr(&lower[bs.saturating_sub(200)..bs], "lang=\"") {
                chosen = li;
            }
        }
        let _ = open_tag_end;
        let _ = tag_text;
        let content = &text[bs..be];
        if !chosen.is_empty() {
            if let Some(cix) = LANGS.iter().position(|l| l.name == chosen) {
                let (cst, cblobs) = count(&LANGS[cix], content);
                let entry = blobs.entry(LANGS[cix].name.to_string()).or_default();
                entry.stats.add(&cst);
                merge(&mut entry.blobs, cblobs);
            }
        }
        cursor = be;
    }
    let seg = &text[cursor..];
    count_segment(lang, seg, &mut st, &mut blobs);
    (st, blobs)
}

fn find_lang_attr(s: &str, key: &str) -> Option<&'static str> {
    if let Some(rel) = s.rfind(key) {
        let v = &s[rel + key.len()..];
        let end = v.find('"').unwrap_or(v.len());
        let val = &v[..end];
        for l in crate::langs::LANGS.iter() {
            let mut low = String::new();
            low.push_str(&l.name.to_lowercase());
            if low == val {
                return Some(l.name);
            }
        }
    }
    None
}

fn count_segment(lang: &LangDef, text: &str, st: &mut Stats, blobs: &mut Blobs) {
    let mut p = Parser::new(lang);
    for (start, end) in Lines::new(text) {
        let line = &text[start..end];
        let was_ml = p.in_ml.is_some();
        let was_str = p.in_str.is_some();
        let (code_seen, comment_seen) = p.scan(line);
        classify(st, was_ml, was_str, code_seen, comment_seen);
    }
}
