        self.blanks == 0 && self.code == 0 && self.comments == 0
    }
}

#[derive(Default, Clone, Debug, PartialEq)]
pub struct BlobStats {
    pub stats: Stats,
    pub blobs: BTreeMap<String, BlobStats>,
}

impl BlobStats {
    pub fn total(&self) -> Stats {
        let mut s = self.stats.clone();
        for b in self.blobs.values() {
            s.add(&b.total());
        }
        s
    }
    pub fn total_stats(&self) -> Stats {
        self.total()
    }
}

pub type Blobs = BTreeMap<String, BlobStats>;

/// Iterate over lines of `s`; yields (start, end) where end is the index of the newline.
pub struct Lines<'a> {
    s: &'a str,
    pos: usize,
}
impl<'a> Lines<'a> {
    pub fn new(s: &'a str) -> Self {
        Lines { s, pos: 0 }
    }
}
impl<'a> Iterator for Lines<'a> {
    type Item = (usize, usize);
    fn next(&mut self) -> Option<(usize, usize)> {
        if self.pos >= self.s.len() {
            return None;
        }
        let rest = &self.s[self.pos..];
        match rest.find('\n') {
            Some(i) => {
                let (a, b) = (self.pos, self.pos + i);
                self.pos = b + 1;
                Some((a, b))
            }
            None => {
                let (a, b) = (self.pos, self.s.len());
                self.pos = self.s.len() + 1;
                Some((a, b))
            }
        }
    }
}

/// Parses a single line for a normal language, tracking multi-line comments and strings.
struct Parser<'a> {
    lang: &'a LangDef,
    in_ml: Option<(usize, usize)>,
    in_str: Option<usize>,
}

impl<'a> Parser<'a> {
    fn new(lang: &'a LangDef) -> Self {
        Parser {
            lang,
            in_ml: None,
            in_str: None,
        }
    }
    fn scan(&mut self, line: &str) -> (bool, bool) {
        let mut code_seen = false;
        let mut comment_seen = false;
        let b = line.as_bytes();
        let mut i = 0usize;
        while i < b.len() {
            if let Some(qi) = self.in_str {
                let c = b[i] as char;
                if c == '\\' {
                    if i + 1 < b.len() {
                        i += 2;
                    } else {
                        i += 1;
                    }
                    code_seen = true;
                    continue;
                }
                if c == self.lang.quotes[qi].chars().next().unwrap() {
                    self.in_str = None;
                    i += 1;
                    continue;
                }
                code_seen = true;
                i += 1;
                continue;
            }
            if let Some((mi, depth)) = self.in_ml {
                let (open, close) = self.lang.multi_line[mi];
                if line[i..].starts_with(close) {
                    if depth <= 1 {
                        self.in_ml = None;
                    } else {
                        self.in_ml = Some((mi, depth - 1));
                    }
                    comment_seen = true;
                    i += close.len();
                    continue;
                }
                if self.lang.nested && line[i..].starts_with(open) {
                    self.in_ml = Some((mi, depth + 1));
                    comment_seen = true;
                    i += open.len();
                    continue;
                }
                comment_seen = true;
                i += 1;
                continue;
            }
            let c = b[i] as char;
            if c.is_whitespace() {
                i += 1;
                continue;
            }
            // longest match across multi-line opens, line comments, quotes
            let mut best: Option<(usize, u8)> = None;
            for (k, (o, _)) in self.lang.multi_line.iter().enumerate() {
                if line[i..].starts_with(o.as_bytes()) {
                    let l = o.len();
                    if best.map(|(bl, _)| l > bl).unwrap_or(true) {
                        best = Some((l, 100 + k as u8));
                    }
                }
            }
            for (k, t) in self.lang.line_comments.iter().enumerate() {
                if line[i..].starts_with(t.as_bytes()) {
                    let l = t.len();
                    let better = match best {
                        None => true,
                        Some((bl, bk)) => l > bl || (l == bl && bk >= 200),
                    };
                    if better {
                        best = Some((l, 200 + k as u8));
                    }
                }
            }
            for (k, q) in self.lang.quotes.iter().enumerate() {
                if c == q.chars().next().unwrap() && best.is_none() {
                    best = Some((1, 50 + k as u8));
                }
            }
            match best {
                Some((_, kind)) if kind >= 200 => {
                    comment_seen = true;
                    break;
                }
                Some((l, kind)) if kind >= 100 => {
                    let k = (kind - 100) as usize;
                    self.in_ml = Some((k, 1));
                    comment_seen = true;
                    i += l;
                }
                Some((_, kind)) => {
                    let k = (kind - 50) as usize;
                    self.in_str = Some(k);
                    code_seen = true;
                    i += 1;
                }
                None => {
                    code_seen = true;
                    i += 1;
                }
            }
        }
        (code_seen, comment_seen)
    }
}

fn classify(st: &mut Stats, was_ml: bool, was_str: bool, code_seen: bool, comment_seen: bool) {
    if was_ml {
        st.comments += 1;
    } else if was_str || code_seen {
        st.code += 1;
    } else if comment_seen {
        st.comments += 1;
    } else {
        st.blanks += 1;
    }
}

fn count_lines(lang: &LangDef, text: &str, st: &mut Stats) {
    let mut p = Parser::new(lang);
    for (start, end) in Lines::new(text) {
        let line = &text[start..end];
        let was_ml = p.in_ml.is_some();
        let was_str = p.in_str.is_some();
        let (code_seen, comment_seen) = p.scan(line);
        classify(st, was_ml, was_str, code_seen, comment_seen);
    }
}

fn count_comments_only(text: &str, st: &mut Stats) {
