{"command": "cat > src/walk.rs <<'RSEOF'
use std::path::{Path, PathBuf};
use std::fs;

pub struct WalkOptions {
    pub hidden: bool,
    pub no_ignore: bool,
    pub no_ignore_parent: bool,
    pub no_ignore_dot: bool,
    pub no_ignore_vcs: bool,
    pub excludes: Vec<String>,
}

#[derive(Clone, Debug)]
struct Pattern {
    negated: bool,
    dir_only: bool,
    anchored: bool,
    segs: Vec<String>,
    base: PathBuf,
}

fn is_glob_char(c: char) -> bool {
    c == '*' || c == '?' || c == '[' || c == ']'
}

/// Match a single pattern segment against a path component.
fn match_seg(pat: &str, name: &str) -> bool {
    // simple glob matching with *, ?, [..]
    let p: Vec<char> = pat.chars().collect();
    let n: Vec<char> = name.chars().collect();
    fn go(p: &[char], n: &[char]) -> bool {
        if p.is_empty() {
            return n.is_empty();
        }
        match p[0] {
            '*' => {
                for i in 0..=n.len() {
                    if go(&p[1..], &n[i..]) {
                        return true;
                    }
                }
                false
            }
            '?' => {
                if n.is_empty() {
                    false
                } else {
                    go(&p[1..], &n[1..])
                }
            }
            '[' => {
                if n.is_empty() {
                    return false;
                }
                // find the closing ]
                let mut i = 1;
                let neg = if p.len() > i && (p[i] == '!' || p[i] == '^') {
                    i += 1;
                    true
                } else {
                    false
                };
                let mut matched = false;
                let mut first = true;
                while i < p.len() && (p[i] != ']' || first) {
                    first = false;
                    if i + 2 < p.len() && p[i + 1] == '-' && p[i + 2] != ']' {
                        if n[0] >= p[i] && n[0] <= p[i + 2] {
                            matched = true;
                        }
                        i += 3;
                    } else {
                        if n[0] == p[i] {
                            matched = true;
                        }
                        i += 1;
                    }
                }
                if i >= p.len() {
                    return false; // unterminated class: treat literally
                }
                if matched != neg {
                    go(&p[i + 1..], &n[1..])
                } else {
                    false
                }
            }
            '\\' => {
                if p.len() > 1 {
                    if n.is_empty() {
                        false
                    } else if n[0] == p[1] {
                        go(&p[2..], &n[1..])
                    } else {
                        false
                    }
                } else {
                    false
                }
            }
            c => {
                if n.is_empty() {
                    false
                } else if n[0] == c {
                    go(&p[1..], &n[1..])
                } else {
                    false
                }
            }
        }
    }
    go(&p, &n)
}

impl Pattern {
    fn parse(line: &str, base: &Path) -> Option<Pattern> {
        let mut s = line;
        if s.starts_with('!') {
            // negation
            let p = Pattern::parse_inner(&s[1..], base, true);
            return p;
        }
        if s.starts_with('#') {
            return None;
        }
        Pattern::parse_inner(s, base, false)
    }
    fn parse_inner(s: &str, base: &Path, negated: bool) -> Option<Pattern> {
        if s.is_empty() {
            return None;
        }
        // unescape
        let mut pat = String::new();
        let mut chars = s.chars().peekable();
        while let Some(c) = chars.next() {
            if c == '\\' {
                if let Some(&n) = chars.peek() {
                    if n == ' ' || n == '#' || n == '!' || n == '*' || n == '?' || n == '[' {
                        pat.push(n);
                        chars.next();
                        continue;
                    }
                }
                pat.push(c);
            } else {
                pat.push(c);
            }
        }
        // trailing spaces are stripped unless escaped
        let pat = pat.trim_end().to_string();
        if pat.is_empty() {
            return None;
        }
        let mut dir_only = false;
        let mut p = pat.as_str();
        if p.ends_with('/') {
            dir_only = true;
            p = &p[..p.len() - 1];
        }
        let anchored = p.contains('/');
