            '*' => {
                for i in 0..=n.len() {
                    if go(&p[1..], &n[i..]) {
                        return true;
                    }
                }
                false
            }
            '?' => {
                if n.is_empty() {
                    false
                } else {
                    go(&p[1..], &n[1..])
                }
            }
