    fn parse_inner(s: &str, base: &Path, negated: bool) -> Option<Pattern> {
        if s.is_empty() {
            return None;
        }
        // unescape
        let mut pat = String::new();
        let mut chars = s.chars().peekable();
        while let Some(c) = chars.next() {
            if c == '\\' {
                if let Some(&n) = chars.peek() {
                    if n == ' ' || n == '#' || n == '!' || n == '*' || n == '?' || n == '[' {
                        pat.push(n);
                        chars.next();
                        continue;
                    }
                }
                pat.push(c);
            } else {
                pat.push(c);
            }
        }
        // trailing spaces are stripped unless escaped
        let pat = pat.trim_end().to_string();
        if pat.is_empty() {
            return None;
        }
        let mut dir_only = false;
        let mut p = pat.as_str();
        if p.ends_with('/') {
            dir_only = true;
            p = &p[..p.len() - 1];
        }
        let anchored = p.contains('/');
        let anchored = if p.starts_with('/') { true } else { anchored };
        let p = p.trim_start_matches('/');
        let segs: Vec<String> = p.split('/').map(|x| x.to_string()).collect();
        Some(Pattern {
            negated,
            dir_only,
            anchored,
            segs,
            base: base.to_path_buf(),
        })
    }

    /// Returns Some(true) if the path is ignored, Some(false) if whitelisted, None if no match
    fn matches(&self, path: &Path, is_dir: bool) -> Option<bool> {
        let rel = match path.strip_prefix(&self.base) {
            Ok(r) => r,
            Err(_) => return None,
        };
        let comps: Vec<&std::ffi::OsStr> = rel.components().map(|c| c.as_os_str()).collect();
        if comps.is_empty() {
            return None;
        }
        let names: Vec<String> = comps.iter().map(|c| c.to_string_lossy().to_string()).collect();
        if !self.anchored {
            // basename match at any level
            for i in 0..names.len() {
                if match_seg(&self.segs[0], &names[i]) {
                    if self.dir_only && i != names.len() - 1 {
                        return None;
                    }
                    if self.dir_only && !is_dir {
                        return None;
                    }
                    return Some(!self.negated);
                }
            }
            return None;
        }
        // anchored: match the segment sequence from the start
        if self.segs.is_empty() {
            return None;
        }
        // handle leading **
        let mut si = 0usize;
        let mut ci = 0usize;
        if self.segs[0] == "**" {
            si = 1;
            if si >= self.segs.len() {
                // ** matches everything below
                if self.dir_only && !is_dir {
                    return None;
                }
                return Some(!self.negated);
            }
        }
        // try to match the sequence starting at each component index
        let mut start = ci;
        loop {
            if let Some(m) = self.match_seq(&names, start, si) {
                if self.dir_only {
                    // the matched path must be a directory
                    let end = start + (self.segs.len() - if self.segs[0] == "**" { 1 } else { 0 });
                    let _ = end;
                    if !is_dir {
                        return None;
                    }
                }
                return Some(!self.negated);
            }
            if self.segs[0] == "**" {
                if start >= names.len() {
                    break;
                }
                start += 1;
            } else {
                break;
            }
        }
        None
    }

    fn match_seq(&self, names: &[String], start: usize, si: usize) -> bool {
        let segs: Vec<String> = if self.segs[0] == "**" {
            self.segs[1..].to_vec()
        } else {
            self.segs.clone()
        };
        if start + segs.len() > names.len() {
            return false;
        }
        for (i, s) in segs.iter().enumerate() {
            if s == "**" {
                // matches zero or more components
                let rest = &segs[i + 1..];
                for k in start + i..=names.len() {
                    if Self::match_rest(rest, names, k) {
                        return true;
                    }
                }
                return false;
            }
            if !match_seg(s, &names[start + i]) {
                return false;
            }
        }
        // all segments matched; the path may have extra components if this is a dir pattern
        true
    }

    fn match_rest(segs: &[String], names: &[String], start: usize) -> bool {
        if segs.is_empty() {
            return true;
        }
        if start + segs.len() > names.len() {
            return false;
        }
        for (i, s) in segs.iter().enumerate() {
            if s == "**" {
                return Self::match_rest(&segs[i + 1..], names, start + i)
                    || Self::match_rest(segs, names, start + 1);
            }
            if !match_seg(s, &names[start + i]) {
                return false;
            }
        }
        true
    }
}

#[derive(Default)]
struct IgnoreSet {
    patterns: Vec<Pattern>,
}

impl IgnoreSet {
    fn add_file(&mut self, path: &Path, base: &Path) {
        if let Ok(content) = fs::read_to_string(path) {
            for line in content.lines() {
                if let Some(p) = Pattern::parse(line, base) {
                    self.patterns.push(p);
                }
            }
        }
    }
    /// None = no decision, Some(true) = ignore, Some(false) = whitelist
    fn matched(&self, path: &Path, is_dir: bool) -> Option<bool> {
        let mut last: Option<bool> = None;
        for p in &self.patterns {
            if let Some(m) = p.matches(path, is_dir) {
                last = Some(m);
            }
        }
        last
    }
}

fn has_git_dir(dir: &Path) -> bool {
    dir.join(".git").exists()
}

fn is_git_repo(dir: &Path) -> bool {
    let mut d = Some(dir);
    while let Some(c) = d {
        if has_git_dir(c) {
            return true;
        }
        d = c.parent();
    }
    false
}

pub fn walk(paths: &[PathBuf], opts: &WalkOptions) -> Vec<PathBuf> {
    let mut out: Vec<PathBuf> = Vec::new();
    let excl = build_exclude(opts);
    for p in paths {
        let meta = fs::metadata(p);
        match meta {
            Ok(m) if m.is_file() => {
                out.push(p.clone());
            }
            Ok(m) if m.is_dir() => {
                walk_dir(p, p, opts, &excl, &mut out);
            }
            _ => {}
        }
    }
    out
}

fn build_exclude(opts: &WalkOptions) -> IgnoreSet {
    let mut s = IgnoreSet::default();
    for e in &opts.excludes {
        if let Some(p) = Pattern::parse(e, Path::new("")) {
            s.patterns.push(p);
        }
    }
    s
}

fn walk_dir(
    root: &Path,
    dir: &Path,
    opts: &WalkOptions,
    excl: &IgnoreSet,
    out: &mut Vec<PathBuf>,
) {
    // gather ignore files for this directory
    let mut set = IgnoreSet::default();
    let use_dot = !opts.no_ignore && !opts.no_ignore_dot;
    let use_vcs = !opts.no_ignore && !opts.no_ignore_vcs;
    if use_vcs && is_git_repo(dir) {
        set.add_file(&dir.join(".gitignore"), dir);
        set.add_file(&dir.join(".git/info/exclude"), dir);
    }
    if use_dot {
        set.add_file(&dir.join(".ignore"), dir);
        set.add_file(&dir.join(".tokeignore"), dir);
    }
    // parent ignore files
    if !opts.no_ignore && !opts.no_ignore_parent {
        let mut p = dir.parent();
        while let Some(par) = p {
            let mut ps = IgnoreSet::default();
            if use_vcs && has_git_dir(par) {
                ps.add_file(&par.join(".gitignore"), par);
            }
            if use_dot {
                ps.add_file(&par.join(".ignore"), par);
                ps.add_file(&par.join(".tokeignore"), par);
            }
            // merge
            set.patterns.extend(ps.patterns);
            p = par.parent();
        }
    }
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    let mut items: Vec<(PathBuf, bool)> = Vec::new();
    for e in entries.flatten() {
        let path = e.path();
        let name = e.file_name().to_string_lossy().to_string();
        let is_dir = match fs::metadata(&path) {
            Ok(m) => m.is_dir(),
            Err(_) => false,
        };
        if !opts.hidden && name.starts_with('.') {
            continue;
        }
        // ignore matching
        if !opts.no_ignore {
            if let Some(m) = set.matched(&path, is_dir) {
                if m {
                    continue;
                }
            }
        }
        if excl.matched(&path, is_dir).unwrap_or(false) {
            continue;
        }
        items.push((path, is_dir));
    }
    items.sort_by(|a, b| a.0.cmp(&b.0));
    for (path, is_dir) in items {
        if is_dir {
            walk_dir(root, &path, opts, excl, out);
        } else {
            out.push(path);
        }
    }
}
RSEOF
echo ok"}

{"command": "cat > src/format.rs <<'RSEOF'
use crate::count::{BlobStats, Stats};
use crate::langs::LANGS;

pub enum NumFmt {
    Plain,
    Commas,
    Dots,
    Underscores,
}

impl NumFmt {
    pub fn fmt(&self, n: usize) -> String {
        match self {
            NumFmt::Plain => n.to_string(),
            _ => {
                let sep = match self {
                    NumFmt::Commas => ',',
                    NumFmt::Dots => '.',
                    NumFmt::Underscores => '_',
                    _ => ',',
                };
                let s = n.to_string();
                let b = s.as_bytes();
                let mut out = String::new();
                for (i, c) in b.iter().enumerate() {
                    if i > 0 && (b.len() - i) % 3 == 0 {
                        out.push(sep);
                    }
                    out.push(*c as char);
                }
                out
            }
        }
    }
}

pub struct Display<'a> {
    pub width: usize,
    pub fmt: &'a NumFmt,
    pub files: bool,
    pub compact: bool,
}

impl<'a> Display<'a> {
    pub fn row_len(&self) -> usize {
        self.width - 1
    }
    pub fn separator(&self, c: char) -> String {
        std::iter::repeat(c).take(self.width).collect()
    }

    fn num_field(&self, v: usize, out: &mut String, end_off: usize, buf: &mut Vec<char>) {
        let s = self.fmt.fmt(v);
        let chars: Vec<char> = s.chars().collect();
        let n = chars.len();
        let start = end_off.saturating_sub(n);
        while buf.len() < start {
            buf.push(' ');
        }
        for c in chars {
            buf.push(c);
        }
        let _ = out;
    }

    /// Build a row: name at offset 1 (or 4 for children), numbers right-aligned.
    pub fn build_row(
        &self,
        name: &str,
        prefix: usize,
        files: Option<usize>,
        st: &Stats,
        inaccurate: bool,
        trunc_width: usize,
    ) -> String {
        let row_len = self.row_len();
        let mut buf: Vec<char> = vec![' '; row_len];
        let mut nm: String = name.to_string();
        if nm.chars().count() > trunc_width {
            let keep = trunc_width - 1;
            nm = nm.chars().take(keep).collect::<String>() + "|";
        }
        let mut ci = prefix;
        for c in nm.chars() {
            if ci < row_len {
                buf[ci] = c;
            }
            ci += 1;
        }
        if inaccurate {
            // " (!)" right after the name field
            let mark = " (!)";
            let mut mi = prefix + self.lang_field_width();
            for c in mark.chars() {
                if mi < row_len {
                    buf[mi] = c;
                }
                mi += 1;
            }
        }
        let cols: Vec<usize> = if files.is_some() {
            vec![self.width - 54, self.width - 41, self.width - 28, self.width - 15, self.width - 2]
        } else {
            vec![self.width - 41, self.width - 28, self.width - 15, self.width - 2]
        };
        let vals: Vec<usize> = match files {
            Some(f) => vec![f, st.lines(), st.code, st.comments, st.blanks],
            None => vec![st.lines(), st.code, st.comments, st.blanks],
        };
        for (i, v) in vals.iter().enumerate() {
            let s = self.fmt.fmt(*v);
            let chars: Vec<char> = s.chars().collect();
            let end = cols[i] - 1;
            let start = end.saturating_sub(chars.len());
            for (j, c) in chars.iter().enumerate() {
                if start + j < row_len {
                    buf[start + j] = *c;
            }
            }
        }
        buf.into_iter().collect()
    }

    fn lang_field_width(&self) -> usize {
        self.width - 66
    }
}

pub struct LangRow<'a> {
    pub name: &'a str,
    pub files: usize,
    pub stats: &'a Stats,
    pub children: &'a [(usize, Stats)],
    pub inaccurate: bool,
}

pub fn lang_index_by_name(name: &str) -> Option<usize> {
    LANGS.iter().position(|l| l.name == name)
}

pub fn display_languages(
    d: &Display,
    rows: &[LangRow],
    out: &mut String,
) {
    out.push_str(&d.separator('━'));
    out.push('\n');
    // header
    let hdr = build_header(d);
    out.push_str(&hdr);
    out.push('\n');
    out.push_str(&d.separator('━'));
    out.push('\n');
    let n = rows.len();
    for (i, r) in rows.iter().enumerate() {
        let trunc = d.width - 63;
        out.push_str(&d.build_row(r.name, 1, Some(r.files), r.stats, r.inaccurate, trunc));
        out.push('\n');
        for (cix, cst) in r.children {
            let cname = &LANGS[*cix].name;
            let trunc = d.width - 66;
            let line = d.build_row(&format!("|- {}", cname), 1, Some(0), cst, false, 0);
            // build child row manually: prefix " |- " then name
            let s = build_child_row(d, cname, Some(0), cst, trunc);
            let _ = line;
            out.push_str(&s);
            out.push('\n');
        }
        if !r.children.is_empty() {
            let mut total = r.stats.clone();
            for (_c, cst) in r.children {
                total.add(cst);
            }
            let trunc = d.width - 63;
            out.push_str(&d.build_row("(Total)", 1, None, &total, false, trunc));
            out.push('\n');
        }
        if i + 1 < n {
            out.push_str(&d.separator('─'));
            out.push('\n');
        }
    }
    out.push_str(&d.separator('━'));
    out.push('\n');
    // total row
    let mut tf = 0usize;
    let mut tt = Stats::default();
    for r in rows {
        tf += r.files;
        tt.add(r.stats);
        for (_c, cst) in &r.children {
            tt.add(cst);
        }
    }
    let inaccurate = rows.iter().any(|r| r.inaccurate);
    out.push_str(&d.build_row("Total", 1, Some(tf), &tt, inaccurate, d.width - 63));
    out.push('\n');
    out.push_str(&d.separator('━'));
    out.push('\n');
}

fn build_header(d: &Display) -> String {
    let row_len = d.row_len();
    let mut buf: Vec<char> = vec![' '; row_len];
    let labels = ["Language", "Files", "Lines", "Code", "Comments", "Blanks"];
    let ends: Vec<usize> = vec![
        d.width - 67 + 8,
        d.width - 54,
        d.width - 41,
        d.width - 28,
        d.width - 15,
        d.width - 2,
    ];
    for (i, l) in labels.iter().enumerate() {
        let chars: Vec<char> = l.chars().collect();
        let end = ends[i] - 1;
        let start = end + 1 - chars.len();
        for (j, c) in chars.iter().enumerate() {
            if start + j < row_len {
                buf[start + j] = *c;
            }
        }
    }
    buf.into_iter().collect()
}

fn build_child_row(
    d: &Display,
    name: &str,
    files: Option<usize>,
    st: &Stats,
    trunc: usize,
) -> String {
    let _ = trunc;
    let _ = files;
    let _ = st;
    let _ = name;
    let _ = d;
    String::new()
}
