        "sort" => "sort",
        "rsort" => "rsort",
        "types" => "types",
        "num-format" => "num_format_style",
        _ => name,
    }
}

fn possible_values(name: &str) -> Option<&'static str> {
    match name {
        "output" => None,
        "streaming" => Some("simple, json"),
