        "columns" => "columns",
        "exclude" => "exclude",
        "input" => "input",
        "output" => "output",
        "streaming" => "streaming",
        "sort" => "sort",
        "rsort" => "rsort",
        "types" => "types",
        "num-format" => "num_format",
        _ => unreachable!(),
    };
