        "columns" => {
            match val.parse::<usize>() {
                Ok(v) => conf.columns = Some(v),
                Err(e) => {
                    let reason = if val.chars().all(|c| c.is_ascii_digit()) && !val.is_empty() {
                        "number too large to fit in target type"
                    } else {
                        "invalid digit found in string"
                    };
                    print_value_error(bin, "--columns <columns>", val, reason, None);
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--columns <columns>".into());
        }
        "exclude" => {
            conf.excludes.push(val.to_string());
            used_out.push("--exclude <exclude>".into());
        }
        "input" => {
            conf.file_input = Some(val.to_string());
            used_out.push("--input <file_input>".into());
        }
        "output" => {
            match val {
                "json" => conf.output = Some("json".into()),
                "yaml" | "cbor" => {
                    let fmt = val;
                    let mut msg = format!("invalid value '{}' for '--output <output>': This version of tokei was compiled without any '{}' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features {}\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n", val, fmt, fmt);
