                    eprint!("error: {}\n\n", msg);
                    eprintln!("For more information, try '--help'.");
                    return Err(CliError { message: String::new(), help: false });
                }
                _ => {
                    print_value_error(bin, "--output <output>", val, &format!("\"{}\" is not a supported serialization format", val), None);
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--output <output>".into());
        }
        "streaming" => {
            match val {
                "simple" | "json" => conf.streaming = Some(val.to_string()),
                _ => {
                    print_value_error(bin, "--streaming <streaming>", val, "", Some("simple, json"));
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--streaming <streaming>".into());
        }
        "sort" => {
            match val {
                "files" | "lines" | "blanks" | "code" | "comments" => conf.sort = Some(val.to_string()),
                _ => {
                    print_value_error(bin, "--sort <sort>", val, "", Some("files, lines, blanks, code, comments"));
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--sort <sort>".into());
        }
        "rsort" => {
            match val {
                "files" | "lines" | "blanks" | "code" | "comments" => conf.rsort = Some(val.to_string()),
                _ => {
                    print_value_error(bin, "--rsort <rsort>", val, "", Some("files, lines, blanks, code, comments"));
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--rsort <rsort>".into());
        }
        "types" => {
            for t in val.split(',') {
                conf.types.push(t.to_string());
            }
            used_out.push("--types <types>".into());
        }
        "num-format" => {
            match val {
                "commas" | "dots" | "plain" | "underscores" => conf.num_format = Some(val.to_string()),
                _ => {
                    print_value_error(bin, "--num-format <num_format_style>", val, "", Some("commas, dots, plain, underscores"));
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--num-format <num_format_style>".into());
        }
        _ => {}
    }
    Ok(None)
}

pub fn print_help(bin: &str) {
    print!("{}", HELP.replace("{BIN}", bin));
}
RSEOF
echo ok"}

