        "types" => "types",
        "num-format" => "num_format",
        _ => unreachable!(),
    };
    if seen.contains(&key) && name != "exclude" && name != "types" {
        let argname = format!("--{} <{}>", display_name(name), value_name(name));
        return Err(dup_error(bin, &argname));
    }
    if key != "exclude" && key != "types" {
        seen.push(key);
    }
    match name {
        "columns" => {
            match val.parse::<usize>() {
                Ok(v) => conf.columns = Some(v),
                Err(e) => {
                    let reason = if val.chars().all(|c| c.is_ascii_digit()) && !val.is_empty() {
                        "number too large to fit in target type"
                    } else {
                        "invalid digit found in string"
                    };
                    print_value_error(bin, "--columns <columns>", val, reason, None);
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--columns <columns>".into());
        }
        "exclude" => {
            conf.excludes.push(val.to_string());
            used_out.push("--exclude <exclude>".into());
        }
        "input" => {
            conf.file_input = Some(val.to_string());
            used_out.push("--input <file_input>".into());
        }
        "output" => {
            match val {
                "json" => conf.output = Some("json".into()),
                "yaml" | "cbor" => {
                    let fmt = val;
                    let mut msg = format!("invalid value '{}' for '--output <output>': This version of tokei was compiled without any '{}' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features {}\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n", val, fmt, fmt);
                    let _ = &mut msg;
                    eprint!("error: {}\n\n", msg);
                    eprintln!("For more information, try '--help'.");
                    return Err(CliError { message: String::new(), help: false });
                }
                _ => {
                    print_value_error(bin, "--output <output>", val, &format!("\"{}\" is not a supported serialization format", val), None);
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--output <output>".into());
        }
        "streaming" => {
            match val {
                "simple" | "json" => conf.streaming = Some(val.to_string()),
                _ => {
                    print_value_error(bin, "--streaming <streaming>", val, "", Some("simple, json"));
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--streaming <streaming>".into());
        }
        "sort" => {
            match val {
                "files" | "lines" | "blanks" | "code" | "comments" => conf.sort = Some(val.to_string()),
                _ => {
                    print_value_error(bin, "--sort <sort>", val, "", Some("files, lines, blanks, code, comments"));
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--sort <sort>".into());
        }
        "rsort" => {
            match val {
                "files" | "lines" | "blanks" | "code" | "comments" => conf.rsort = Some(val.to_string()),
                _ => {
                    print_value_error(bin, "--rsort <rsort>", val, "", Some("files, lines, blanks, code, comments"));
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--rsort <rsort>".into());
        }
        "types" => {
            for t in val.split(',') {
                conf.types.push(t.to_string());
            }
            used_out.push("--types <types>".into());
        }
        "num-format" => {
            match val {
                "commas" | "dots" | "plain" | "underscores" => conf.num_format = Some(val.to_string()),
                _ => {
                    print_value_error(bin, "--num-format <num_format_style>", val, "", Some("commas, dots, plain, underscores"));
                    return Err(CliError { message: String::new(), help: false });
                }
            }
            used_out.push("--num-format <num_format_style>".into());
        }
        _ => {}
    }
    Ok(None)
}

pub fn print_help(bin: &str) {
    print!("{}", HELP.replace("{BIN}", bin));
}
RSEOF
echo ok"}

