                "blanks" => e.stats.blanks,
                "code" => e.stats.code,
                "comments" => e.stats.comments,
                _ => 0,
            }
        };
        keys.sort_by(|a, b| {
            let ea = &map[a];
            let eb = &map[b];
            keyfn(eb).cmp(&keyfn(ea)).then(a.cmp(b))
        });
    } else if let Some(s) = &conf.rsort {
        let keyfn = |e: &LangEntry| -> usize {
            match s.as_str() {
