    }
    let width = std::cmp::max(81, conf.columns.unwrap_or(0));
    let fmt = match conf.num_format.as_deref() {
        Some("commas") => format::NumFmt::Commas,
        Some("dots") => format::NumFmt::Dots,
        Some("underscores") => format::NumFmt::Underscores,
        _ => format::NumFmt::Plain,
    };
