    for k in &keys {
        let e = &map[k];
        let mut children: Vec<(usize, Stats)> = Vec::new();
        for (c, rs) in &e.children {
            let cix = langs::LANGS.iter().position(|l| l.name == *c).unwrap_or(0);
            let mut s = Stats::default();
            for r in rs {
                s.add(&r.stats);
                for b in r.blobs.values() {
                    s.add(&b.total());
                }
            }
            children.push((cix, s));
        }
        children.sort_by(|a, b| langs::LANGS[a.0].name.cmp(langs::LANGS[b.0].name));
