    format::display_table(&d, &rows, conf.files, conf.compact, &files, &map, &mut out2);
    out.push_str(&out2);
    print!("{}", out);
}

fn extension_of(p: &Path) -> Option<String> {
    p.extension().map(|e| e.to_string_lossy().to_string())
}

fn lang_for_path(p: &Path) -> Option<usize> {
    let name = p.file_name()?.to_string_lossy().to_string();
    // filename match first (for languages without extensions)
    let lower = name.to_lowercase();
    for (i, l) in langs::LANGS.iter().enumerate() {
        if !l.files.is_empty() && l.files.iter().any(|f| f.to_lowercase() == lower) {
            return Some(i);
        }
    }
    let ext = p.extension()?.to_string_lossy().to_lowercase();
    langs::LANGS
        .iter()
        .position(|l| l.exts.iter().any(|e| e.to_lowercase() == ext))
}

fn display_path(f: &Path, roots: &[PathBuf]) -> String {
    for r in roots {
        if let Ok(rel) = f.strip_prefix(r) {
            let joined = r.join(rel);
            return joined.to_string_lossy().to_string();
        }
    }
    f.to_string_lossy().to_string()
}

fn print_input_error(path: &str, _err: &str) {
    eprintln!("Error:\n Failed to parse input file: {}\n", path);
    eprintln!("This version of tokei was compiled without serialization support for the following formats:\n");
    eprintln!("    cbor, json, yaml\n");
    eprintln!("You may want to install any comma separated combination of \"cbor,json,yaml\":\n");
    eprintln!("    cargo install tokei --features \"cbor,json,yaml\"\n");
    eprintln!("Or use the 'all' feature:\n");
    eprintln!("    cargo install tokei --features all\n");
    eprintln!("    ");
}

fn serde_like_parse(_s: &str) -> Option<()> {
    // Minimal validation: tokei only fails when the file cannot be parsed at all.
    Some(())
}
