use crate::json_out::{LangEntry, Report};

pub fn display_table(
    d: &Display,
    rows: &[(String, usize, Stats, Vec<(usize, Stats)>, bool)],
    show_files: bool,
    compact: bool,
    files: &[PathBuf_],
    map: &std::collections::BTreeMap<String, LangEntry>,
    out: &mut String,
) {
    let _ = files;
    let _ = map;
    out.push_str(&d.separator('━'));
    out.push('\n');
    out.push_str(&d.header());
    out.push('\n');
    out.push_str(&d.separator('━'));
    out.push('\n');
    // filter out empty languages
    let visible: Vec<&(String, usize, Stats, Vec<(usize, Stats)>, bool)> = rows
        .iter()
        .filter(|r| r.2.lines() > 0 || !r.3.is_empty())
        .collect();
    let n = visible.len();
    for (i, r) in visible.iter().enumerate() {
        out.push_str(&d.row("", &r.0, Some(r.1), &r.2, r.4));
        out.push('\n');
        if !compact {
            for (cix, cst) in &r.3 {
                out.push_str(&d.row("|- ", &crate::langs::LANGS[*cix].name, Some(0), cst, false));
                out.push('\n');
            }
            if !r.3.is_empty() {
                let mut total = r.2.clone();
                for (_c, cst) in &r.3 {
                    total.add(cst);
                }
                out.push_str(&d.row("", "(Total)", None, &total, false));
                out.push('\n');
            }
        }
        if i + 1 < n {
            out.push_str(&d.separator('─'));
            out.push('\n');
        }
        if show_files {
            print_files(d, r, compact, map, out);
        }
    }
    out.push_str(&d.separator('━'));
    out.push('\n');
    let mut tf = 0usize;
    let mut tt = Stats::default();
    for r in rows {
        tf += r.1;
        tt.add(&r.2);
        for (_c, cst) in &r.3 {
            tt.add(cst);
        }
    }
    let inaccurate = rows.iter().any(|r| r.4);
    out.push_str(&d.row("", "Total", Some(tf), &tt, inaccurate));
    out.push('\n');
    out.push_str(&d.separator('━'));
    out.push('\n');
}

fn print_files(
    d: &Display,
    r: &(String, usize, Stats, Vec<(usize, Stats)>, bool),
    compact: bool,
    map: &std::collections::BTreeMap<String, LangEntry>,
    out: &mut String,
) {
    let entry = match map.get(&r.0) {
        Some(e) => e,
        None => return,
    };
    if entry.reports.is_empty() {
        return;
    }
    let mut reports: Vec<&Report> = entry.reports.iter().collect();
    reports.sort_by(|a, b| {
        let ka = if a.blobs.is_empty() { 0 } else { 1 };
        let kb = if b.blobs.is_empty() { 0 } else { 1 };
        ka.cmp(&kb).then(a.name.cmp(&b.name))
    });
    let mut first_in_group = true;
    for rep in reports {
        if !compact && !rep.blobs.is_empty() {
            if first_in_group {
                let mut nm = rep.name.clone();
                if nm.chars().count() > d.width - 54 {
                    let keep = d.width - 55;
                    nm = nm.chars().skip(nm.chars().count() - keep).collect::<String>();
                    nm = format!("|{}", nm);
                }
                out.push(' ');
                out.push_str(&nm);
                out.push('\n');
            } else {
                let mut nm = rep.name.clone();
                if nm.chars().count() > d.width - 55 {
                    let keep = d.width - 56;
                    nm = nm.chars().skip(nm.chars().count() - keep).collect::<String>();
                    nm = format!("|{}", nm);
                }
                out.push_str(&d.file_separator(&nm));
                out.push('\n');
            }
            // own language row
            out.push_str(&d.row("|- ", &r.0, Some(0), &rep.stats, false));
            out.push('\n');
            let mut names: Vec<&String> = rep.blobs.keys().collect();
            names.sort();
            for cn in names {
                let cb = &rep.blobs[cn];
                out.push_str(&d.row("|- ", cn, Some(0), &cb.stats, false));
                out.push('\n');
            }
            out.push_str(&d.row("", &rep.name, None, &rep.stats, false));
            out.push('\n');
        } else {
            out.push_str(&d.row("", &rep.name, None, &rep.stats, false));
            out.push('\n');
        }
        first_in_group = false;
    }
}
