use std::collections::BTreeMap;
use crate::langs::{LangDef, Kind, LANGS};

#[derive(Default, Clone, Debug, PartialEq)]
pub struct Stats {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
}

impl Stats {
    pub fn lines(&self) -> usize {
        self.blanks + self.code + self.comments
    }
    pub fn add(&mut self, o: &Stats) {
        self.blanks += o.blanks;
        self.code += o.code;
        self.comments += o.comments;
    }
    pub fn is_empty(&self) -> bool {
        self.blanks == 0 && self.code == 0 && self.comments == 0
    }
}

#[derive(Default, Clone, Debug, PartialEq)]
pub struct BlobStats {
    pub stats: Stats,
    pub blobs: BTreeMap<String, BlobStats>,
}

impl BlobStats {
    pub fn total(&self) -> Stats {
        let mut s = self.stats.clone();
        for b in self.blobs.values() {
            s.add(&b.total());
        }
        s
    }
}

pub type Blobs = BTreeMap<String, BlobStats>;

/// Iterate over lines of `s`; yields (start, end) where end is the index of the newline.
pub struct Lines<'a> {
    s: &'a str,
    pos: usize,
}
impl<'a> Lines<'a> {
    pub fn new(s: &'a str) -> Self {
        Lines { s, pos: 0 }
    }
}
impl<'a> Iterator for Lines<'a> {
    type Item = (usize, usize);
    fn next(&mut self) -> Option<(usize, usize)> {
        if self.pos >= self.s.len() {
            return None;
        }
        let rest = &self.s[self.pos..];
        match rest.find('\n') {
            Some(i) => {
                let (a, b) = (self.pos, self.pos + i);
                self.pos = b + 1;
                Some((a, b))
            }
            None => {
                let (a, b) = (self.pos, self.s.len());
                self.pos = self.s.len() + 1;
                Some((a, b))
            }
        }
    }
}

/// Parses a single line for a normal language, tracking multi-line comments and strings.
#[derive(Clone)]
struct Parser<'a> {
    lang: &'a LangDef,
    in_ml: Option<(usize, usize)>,
    in_str: Option<usize>,
}

impl<'a> Parser<'a> {
    fn new(lang: &'a LangDef) -> Self {
        Parser {
            lang,
            in_ml: None,
            in_str: None,
        }
    }
    fn scan(&mut self, line: &str) -> (bool, bool) {
        let mut code_seen = false;
        let mut comment_seen = false;
        let b = line.as_bytes();
        let mut i = 0usize;
        while i < b.len() {
            if let Some(qi) = self.in_str {
                let c = b[i] as char;
                if c == '\\' {
                    if i + 1 < b.len() {
                        i += 2;
                    } else {
                        i += 1;
                    }
                    code_seen = true;
                    continue;
                }
                if c == self.lang.quotes[qi].chars().next().unwrap() {
                    self.in_str = None;
                    i += 1;
                    continue;
                }
                code_seen = true;
                i += 1;
                continue;
            }
            if let Some((mi, depth)) = self.in_ml {
                let (open, close) = self.lang.multi_line[mi];
                if b[i..].starts_with(close.as_bytes()) {
                    if depth <= 1 {
                        self.in_ml = None;
                    } else {
                        self.in_ml = Some((mi, depth - 1));
                    }
                    comment_seen = true;
                    i += close.len();
                    continue;
                }
                if self.lang.nested && b[i..].starts_with(open.as_bytes()) {
                    self.in_ml = Some((mi, depth + 1));
                    comment_seen = true;
                    i += open.len();
                    continue;
                }
                comment_seen = true;
                i += 1;
                continue;
            }
            let c = b[i] as char;
            if c.is_whitespace() {
                i += 1;
                continue;
            }
            let mut best: Option<(usize, u16)> = None;
            for (k, (o, _)) in self.lang.multi_line.iter().enumerate() {
                if b[i..].starts_with(o.as_bytes()) {
                    let l = o.len();
                    if best.map(|(bl, _)| l > bl).unwrap_or(true) {
                        best = Some((l, 100 + k as u16));
                    }
                }
            }
            for (k, t) in self.lang.line_comments.iter().enumerate() {
                if b[i..].starts_with(t.as_bytes()) {
                    let l = t.len();
                    let better = match best {
                        None => true,
                        Some((bl, bk)) => l > bl || (l == bl && bk >= 200),
                    };
                    if better {
                        best = Some((l, 200 + k as u16));
                    }
                }
            }
            for (k, q) in self.lang.quotes.iter().enumerate() {
                if c == q.chars().next().unwrap() && best.is_none() {
                    best = Some((1, 50 + k as u16));
                }
            }
            match best {
                Some((_, kind)) if kind >= 200 => {
                    comment_seen = true;
                    break;
                }
                Some((l, kind)) if kind >= 100 => {
                    let k = (kind - 100) as usize;
                    self.in_ml = Some((k, 1));
                    comment_seen = true;
                    i += l;
                }
                Some((_, kind)) => {
                    let k = (kind - 50) as usize;
                    self.in_str = Some(k);
                    code_seen = true;
                    i += 1;
                }
                None => {
                    code_seen = true;
                    i += 1;
                }
            }
        }
        (code_seen, comment_seen)
    }
}

fn classify(st: &mut Stats, was_ml: bool, was_str: bool, code_seen: bool, comment_seen: bool) {
    if was_ml {
        st.comments += 1;
    } else if was_str || code_seen {
        st.code += 1;
    } else if comment_seen {
        st.comments += 1;
    } else {
        st.blanks += 1;
    }
}

/// Accumulates stats for a language while scanning lines.
struct Counter<'a> {
    lang: &'a LangDef,
    p: Parser<'a>,
    st: Stats,
}

impl<'a> Counter<'a> {
    fn new(lang: &'a LangDef) -> Self {
        Counter {
            lang,
            p: Parser::new(lang),
            st: Stats::default(),
        }
    }
    fn line(&mut self, line: &str) {
        let was_ml = self.p.in_ml.is_some();
        let was_str = self.p.in_str.is_some();
        let (code_seen, comment_seen) = self.p.scan(line);
        classify(&mut self.st, was_ml, was_str, code_seen, comment_seen);
    }
    fn comments_only_line(&mut self, line: &str) {
        if line.trim().is_empty() {
            self.st.blanks += 1;
        } else {
            self.st.comments += 1;
        }
    }
}

pub fn count(lang: &LangDef, text: &str) -> (Stats, Blobs) {
    let mut c = Counter::new(lang);
    let mut blobs: Blobs = BTreeMap::new();
    match lang.kind {
        Kind::Comments => {
            for (start, end) in Lines::new(text) {
                c.comments_only_line(&text[start..end]);
            }
        }
        Kind::Markdown => count_markdown(lang, text, true, &mut c, &mut blobs),
        Kind::Html => count_html(lang, text, &mut c, &mut blobs),
        Kind::Rust => count_rust(lang, text, &mut c, &mut blobs),
        Kind::Normal => {
            for (start, end) in Lines::new(text) {
                c.line(&text[start..end]);
            }
        }
    }
    (c.st, blobs)
}

fn add_blob(blobs: &mut Blobs, name: &str, st: Stats, sub: Blobs) {
    let e = blobs.entry(name.to_string()).or_default();
    e.stats.add(&st);
    for (k, v) in sub {
        let e2 = e.blobs.entry(k).or_default();
        e2.stats.add(&v.stats);
        for (k2, v2) in v.blobs {
            e2.blobs.insert(k2, v2);
        }
    }
}

fn fence_lang(info: &str) -> Option<(usize, usize)> {
    if info.is_empty() || info.starts_with(|c: char| c.is_whitespace()) {
        return None;
    }
    let mut end = info.len();
    for (i, c) in info.char_indices() {
        if c == ' ' || c == '\t' || c == ',' {
            end = i;
            break;
        }
    }
    let tok = &info[..end];
    if tok.is_empty() {
        return None;
    }
    lang_by_name_ci(tok).map(|ix| (ix, tok.len()))
}

pub fn lang_by_name_ci(name: &str) -> Option<usize> {
    LANGS
        .iter()
        .position(|l| l.name.to_lowercase() == name.to_lowercase())
}

fn lang_by_lower_name(name: &str) -> Option<usize> {
    LANGS
        .iter()
        .position(|l| l.name.to_lowercase() == name)
}

fn count_markdown(
    lang: &LangDef,
    text: &str,
    comments_only: bool,
    c: &mut Counter,
    blobs: &mut Blobs,
) {
    let mut cursor = 0usize;
    while cursor < text.len() {
        let nl = text[cursor..].find('\n').map(|i| cursor + i);
        let end = nl.unwrap_or(text.len());
        let line = &text[cursor..end];
        let trimmed = line.trim_start();
        let lead = line.len() - trimmed.len();
        if trimmed.starts_with("```") {
            let info = &trimmed[3..];
            if let Some((li, name_len)) = fence_lang(info) {
                let child = &LANGS[li];
                c.st.comments += 1;
                let has_ws = info.trim().contains(|ch: char| ch == ' ' || ch == '\t');
                let block_start = if has_ws {
                    cursor + lead + 3 + name_len
                } else if end < text.len() {
                    end + 1
                } else {
                    text.len()
                };
                let mut closing: Option<usize> = None;
                let mut p = if end < text.len() { end + 1 } else { text.len() };
                while p < text.len() {
                    let nl2 = text[p..].find('\n').map(|i| p + i);
                    let e2 = nl2.unwrap_or(text.len());
                    let l2 = &text[p..e2];
                    if l2.trim_start().starts_with("```") {
                        closing = Some(p);
                        break;
                    }
                    p = if e2 < text.len() { e2 + 1 } else { text.len() + 1 };
                }
                let (block, after) = match closing {
                    Some(cs) => (&text[block_start..cs], cs + 3),
                    None => (&text[block_start..], text.len()),
                };
                let (cst, cblobs) = count(child, block);
                add_blob(blobs, child.name, cst, cblobs);
                cursor = after;
                if cursor < text.len() {
                    let nl3 = text[cursor..].find('\n').map(|i| cursor + i);
                    let e3 = nl3.unwrap_or(text.len());
                    let rem = &text[cursor..e3];
                    if !rem.is_empty() {
                        if comments_only {
                            c.comments_only_line(rem);
                        } else {
                            c.line(rem);
                        }
                    }
                    cursor = if e3 < text.len() { e3 + 1 } else { text.len() };
                }
                continue;
            }
        }
        if comments_only {
            c.comments_only_line(line);
        } else {
            c.line(line);
        }
        cursor = if end < text.len() { end + 1 } else { text.len() };
    }
}

fn count_rust(lang: &LangDef, text: &str, c: &mut Counter, blobs: &mut Blobs) {
    let lines: Vec<(usize, usize)> = Lines::new(text).collect();
    let mut doc_parts: Vec<String> = Vec::new();
    let mut have_doc = false;
    let mut i = 0usize;
    while i < lines.len() {
        let (start, end) = lines[i];
        let line = &text[start..end];
        let trimmed = line.trim_start();
        if !trimmed.is_empty()
            && c.p.in_ml.is_none()
            && c.p.in_str.is_none()
            && (trimmed.starts_with("///") || trimmed.starts_with("//!"))
        {
            have_doc = true;
            doc_parts.push(trimmed[3..].to_string());
            i += 1;
            while i < lines.len() {
                let (s2, e2) = lines[i];
                let l2 = &text[s2..e2];
                if l2.trim().is_empty() {
                    if i + 1 < lines.len() {
                        let (s3, e3) = lines[i + 1];
                        let t3 = text[s3..e3].trim_start();
                        if t3.starts_with("///") || t3.starts_with("//!") {
                            i += 1;
                            continue;
                        }
                    }
                }
                break;
            }
            continue;
        }
        c.line(line);
        i += 1;
    }
    if have_doc {
        let blob = doc_parts.join("\n");
        let blob = blob.trim();
        if !blob.is_empty() {
            if let Some(mix) = LANGS.iter().position(|l| l.name == "Markdown") {
                let (mst, mblobs) = count(&LANGS[mix], blob);
                add_blob(blobs, "Markdown", mst, mblobs);
            }
        }
    }
}

type TagSpec = (&'static str, &'static str, bool, &'static str);

fn html_tags(lang: &LangDef) -> &'static [TagSpec] {
    match lang.name {
        "HTML" => &[
            ("script", "JavaScript", true, "JavaScript"),
            ("style", "CSS", true, "CSS"),
        ],
        "Vue" => &[
            ("script", "JavaScript", false, "JavaScript"),
            ("style", "CSS", true, "CSS"),
            ("template", "HTML", true, "HTML"),
        ],
        "Svelte" => &[
            ("script", "JavaScript", false, "JavaScript"),
            ("style", "CSS", true, "CSS"),
            ("template", "", true, ""),
        ],
        _ => &[],
    }
}

fn count_html(lang: &LangDef, text: &str, c: &mut Counter, blobs: &mut Blobs) {
    let tags = html_tags(lang);
    let lower = text.to_lowercase();
    let mut blocks: Vec<(usize, usize, usize, bool)> = Vec::new();
    for (ti, spec) in tags.iter().enumerate() {
        let tag = spec.0;
        let open = format!("<{}", tag);
        let close = format!("</{}>", tag);
        let mut from = 0usize;
        while let Some(rel) = lower[from..].find(&open) {
            let start = from + rel;
            let after = &text[start + open.len()..];
            if !(after.starts_with('>') || after.starts_with(|ch: char| ch.is_whitespace())) {
                from = start + open.len();
                continue;
            }
            let gt = match after.find('>') {
                Some(g) => start + open.len() + g,
                None => break,
            };
            match lower[gt..].find(&close) {
                Some(cr) => {
                    blocks.push((gt + 1, gt + cr, ti, true));
                    from = gt + cr + close.len();
                }
                None => {
                    blocks.push((gt + 1, text.len(), ti, false));
                    break;
                }
            }
        }
    }
    blocks.sort();
    let mut filtered: Vec<(usize, usize, usize, bool)> = Vec::new();
    let mut last_end = 0usize;
    for b in blocks {
        if b.0 < last_end {
            continue;
        }
        last_end = b.1;
        filtered.push(b);
    }
    let mut cursor = 0usize;
    for (bs, be, ti, closed) in filtered {
        let seg = &text[cursor..bs];
        for (s, e) in Lines::new(seg) {
            c.line(&seg[s..e]);
        }
        let spec = tags[ti];
        let mut chosen = spec.3;
        if spec.2 {
            let tag_text = &text[bs.saturating_sub(400)..bs];
            if let Some(v) = extract_lang_attr(tag_text) {
                chosen = v;
            }
        }
        let content = if closed { &text[bs..be] } else { &text[bs..] };
        if !chosen.is_empty() {
            if let Some(cix) = lang_by_lower_name(chosen) {
                let (cst, cblobs) = count(&LANGS[cix], content);
                add_blob(blobs, LANGS[cix].name, cst, cblobs);
            }
        }
        if closed {
            let close = format!("</{}>", tags[ti].0);
            let crel = lower[bs..].find(&close).unwrap_or(0);
            cursor = bs + crel + close.len();
        } else {
            cursor = text.len();
        }
    }
    let seg = &text[cursor..];
    for (s, e) in Lines::new(seg) {
        c.line(&seg[s..e]);
    }
}

fn extract_lang_attr(s: &str) -> Option<&'static str> {
    let needle = "lang=\"";
    let mut from = 0usize;
    while let Some(rel) = s[from..].find(needle) {
        let start = from + rel + needle.len();
        let v = &s[start..];
        let end = v.find('"').unwrap_or(v.len());
        let val = &v[..end];
        if let Some(ix) = lang_by_lower_name(val) {
            return Some(LANGS[ix].name);
        }
        from = start;
    }
    None
}
